DROP POLICY IF EXISTS "Admins can manage events" ON public.eventos;
CREATE POLICY "Admins can manage events" ON public.eventos FOR ALL TO authenticated USING (has_setor(auth.uid(),'eventos')) WITH CHECK (has_setor(auth.uid(),'eventos'));
DROP POLICY IF EXISTS "Admins manage evento_produtos" ON public.evento_produtos;
CREATE POLICY "Admins manage evento_produtos" ON public.evento_produtos FOR ALL TO authenticated USING (has_setor(auth.uid(),'eventos')) WITH CHECK (has_setor(auth.uid(),'eventos'));
DROP POLICY IF EXISTS "Admins manage produtos" ON public.produtos;
CREATE POLICY "Admins manage produtos" ON public.produtos FOR ALL TO authenticated USING (has_setor(auth.uid(),'produtos')) WITH CHECK (has_setor(auth.uid(),'produtos'));
DROP POLICY IF EXISTS "Admins manage variacoes" ON public.produto_variacoes;
CREATE POLICY "Admins manage variacoes" ON public.produto_variacoes FOR ALL TO authenticated USING (has_setor(auth.uid(),'produtos')) WITH CHECK (has_setor(auth.uid(),'produtos'));
DROP POLICY IF EXISTS "Anyone can view active events" ON public.eventos;
CREATE POLICY "Anyone can view active events" ON public.eventos FOR SELECT TO anon, authenticated USING (ativo = true);
DROP POLICY IF EXISTS "Anyone can view active produtos" ON public.produtos;
CREATE POLICY "Anyone can view active produtos" ON public.produtos FOR SELECT TO anon USING (ativo = true);
CREATE POLICY "Staff view produtos" ON public.produtos FOR SELECT TO authenticated USING (ativo = true OR has_setor(auth.uid(),'produtos') OR has_setor(auth.uid(),'eventos'));
DROP POLICY IF EXISTS "Anyone can view active variacoes" ON public.produto_variacoes;
CREATE POLICY "Anyone can view active variacoes" ON public.produto_variacoes FOR SELECT TO anon USING (ativo = true);
CREATE POLICY "Staff view variacoes" ON public.produto_variacoes FOR SELECT TO authenticated USING (ativo = true OR has_setor(auth.uid(),'produtos') OR has_setor(auth.uid(),'eventos'));
DROP POLICY IF EXISTS "Anyone can view active evento_produtos" ON public.evento_produtos;
CREATE POLICY "Anyone can view active evento_produtos" ON public.evento_produtos FOR SELECT TO anon USING (ativo = true);
CREATE POLICY "Staff view evento_produtos" ON public.evento_produtos FOR SELECT TO authenticated USING (ativo = true OR has_setor(auth.uid(),'eventos'));